// Newsletter sources to backfill
// Each entry: { source, labelId, senders[] }
const SOURCES = [
  { source: 'nik_sharma', author: 'Nik Sharma', labelId: 'Label_422580267025539773', query: 'from:niksharma@workweek.com' },
  { source: 'taylor_holiday', author: 'Taylor Holiday / CTC', labelId: 'Label_527847910175146065', query: 'from:taylorholiday@commonthreadco.com' },
  { source: 'matt_bertulli', author: 'Matt Bertulli', labelId: 'Label_529153241593133290', query: 'from:m@mattbertulli.com' },
  { source: 'chase_dimond', author: 'Chase Dimond', labelId: null, query: 'from:chase@chasedimond.com OR from:ecomemailmarketer@mail.beehiiv.com' },
  { source: 'operators_newsletter', author: 'Operators Newsletter', labelId: 'Label_4710583513291043383', query: 'from:news@operatorscontent.com' },
];

return SOURCES.map(s => ({ json: s }));

// Extract body text from Gmail message
const msg = $json;
const source = $('Source Config').first().json;

// Get plain text body
let bodyText = '';
let bodyHtml = '';

if (msg.payload) {
  const payload = msg.payload;

  // Check direct body
  if (payload.body && payload.body.data) {
    const decoded = Buffer.from(payload.body.data, 'base64').toString('utf-8');
    if (payload.mimeType === 'text/html') bodyHtml = decoded;
    else bodyText = decoded;
  }

  // Check parts
  const parts = payload.parts || [];
  for (const part of parts) {
    if (part.body && part.body.data) {
      const decoded = Buffer.from(part.body.data, 'base64').toString('utf-8');
      if (part.mimeType === 'text/plain' && !bodyText) bodyText = decoded;
      if (part.mimeType === 'text/html' && !bodyHtml) bodyHtml = decoded;
    }
    // Nested parts
    const subparts = part.parts || [];
    for (const sp of subparts) {
      if (sp.body && sp.body.data) {
        const decoded = Buffer.from(sp.body.data, 'base64').toString('utf-8');
        if (sp.mimeType === 'text/plain' && !bodyText) bodyText = decoded;
        if (sp.mimeType === 'text/html' && !bodyHtml) bodyHtml = decoded;
      }
    }
  }
}

// Extract headers
const headers = {};
const rawHeaders = (msg.payload && msg.payload.headers) || msg.headers || [];
for (const h of rawHeaders) {
  headers[h.name.toLowerCase()] = h.value;
}

return [{
  json: {
    email_id: msg.id || msg.messageId,
    source: source.source,
    author: source.author,
    subject: headers['subject'] || '',
    published_at: headers['date'] ? new Date(headers['date']).toISOString() : null,
    sender_email: headers['from'] || '',
    body_html: bodyHtml,
    body_text: bodyText,
  }
}];

const result = $json;
console.log(`email_id=${result.email_id} status=${result.status} insights=${result.insights_count || 0}`);
return [{ json: result }];
